"""Generation Module"""

import xmltodict
import logging


class Generation:
    """Generation class"""

    def __init__(self, logger=None):
        self.logger = logging.getLogger(__name__) if logger is None else logger

    def generate_xml_from_dict(self, dict_to_translate: dict):
        """generate_xml_from_dict method
        :param dict_to_translate: dict which will be translated to xml
        :return: xml
        """
        self.logger.debug(f"Json which will be translated to xml: {dict_to_translate}")
        generated_xml = xmltodict.unparse(dict_to_translate).split('?xml version="1.0" encoding="utf-8"?>\n')[-1]
        self.logger.debug(f"Generated xml: {generated_xml}")
        return generated_xml
